<?php get_header(); ?><main class="inner-page"><section class="page-hero"><div class="container-xl"><span class="section-kicker">Properties</span><h1><?php echo esc_html(estatein_field('property_archive_heading','option','Explore Our Properties')); ?></h1><p><?php echo esc_html(estatein_field('property_archive_description','option','Browse properties by location, type, price, size, and build year.')); ?></p></div></section><section class="content-section pt-0"><div class="container-xl"><?php estatein_property_filters(); ?><div class="row g-4"><?php $q=new WP_Query(estatein_property_query_args());if($q->have_posts()):while($q->have_posts()):$q->the_post(); ?><div class="col-md-6 col-lg-4"><article class="property-card h-100"><?php if(has_post_thumbnail()) the_post_thumbnail('estatein-property-card',['class'=>'property-card-image']); ?><div class="property-card-body"><h2><?php the_title(); ?></h2><p><?php echo esc_html(estatein_field('short_excerpt',get_the_ID(),wp_trim_words(get_the_excerpt(),20))); ?></p><div class="property-meta"><span><?php echo esc_html(estatein_field('bedrooms',get_the_ID(),'—')); ?> Beds</span><span><?php echo esc_html(estatein_field('bathrooms',get_the_ID(),'—')); ?> Baths</span><span><?php echo esc_html(estatein_field('property_size',get_the_ID(),'—')); ?> <?php echo esc_html(estatein_field('property_size_unit',get_the_ID(),'sq ft')); ?></span></div><div class="property-price-row"><strong><?php echo esc_html(estatein_currency(estatein_field('price',get_the_ID()))); ?></strong><a class="btn btn-primary" href="<?php the_permalink(); ?>">View Details</a></div></div></article></div><?php endwhile;else: ?><div class="col-12"><div class="empty-state">No properties match these filters.</div></div><?php endif; ?></div><div class="mt-5"><?php echo paginate_links(['total'=>$q->max_num_pages,'type'=>'list','prev_text'=>'←','next_text'=>'→']); ?></div><?php wp_reset_postdata(); ?></div></section></main><?php get_footer(); ?>
